SELECT Go.IdP, [Pronto intervento Comune].[N#], [Pronto intervento Comune].[Num# progressivo del minore], [Pronto intervento Comune].[ID minore], [Pronto intervento Comune].[Nome MSNA], [Pronto intervento Comune].[Cognome MSNA], [Pronto intervento Comune].[Data di nascita], [Pronto intervento Comune].Cittadinanza, [Pronto intervento Comune].Genere, [Pronto intervento Comune].[Tipologia di accoglienza (struttura/privato)], [Pronto intervento Comune].[Denominazione(struttura/privato)], [Pronto intervento Comune].Indirizzo, [Pronto intervento Comune].[Ente gestore struttura di accoglienza], [Pronto intervento Comune].[Periodo di accoglienza DAL], [Pronto intervento Comune].ora, [Pronto intervento Comune].[Periodo di accoglienza AL], [Pronto intervento Comune].ora1, [Pronto intervento Comune].fuga, [Pronto intervento Comune].note, [Pronto intervento Comune].[struttura di destinazione], [Pronto intervento Comune].retta, [Pronto intervento Comune].gen, [Pronto intervento Comune].feb, [Pronto intervento Comune].mar, [Pronto intervento Comune].apr, [Pronto intervento Comune].mag, [Pronto intervento Comune].giu, [Pronto intervento Comune].lug, [Pronto intervento Comune].ago, [Pronto intervento Comune].set, [Pronto intervento Comune].ott, [Pronto intervento Comune].nov, [Pronto intervento Comune].dic, [Pronto intervento Comune].TOT
FROM [Pronto intervento Comune] RIGHT JOIN (Differenza INNER JOIN [Go] ON Differenza.IdP = Go.IdP) ON ([Pronto intervento Comune].[Cognome MSNA] = Go.Cognome) AND ([Pronto intervento Comune].[Nome MSNA] = Go.Nome) AND ([Pronto intervento Comune].[Data di nascita] = Go.DataN);
